"""Generate per-path global leaderboard effects for the victory situation."""

import sys
import argparse
from pathlib import Path

if hasattr(sys.stdout, "reconfigure"):
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")

import yaml

REPO_ROOT = Path(__file__).resolve().parents[4]
DATA_FILE = REPO_ROOT / "data" / "victory_paths.yaml"
OUT_FILE = REPO_ROOT / "src" / "in_game" / "common" / "scripted_effects" / "towards_victory_leaderboard.txt"

HEADER = """\
# @Generated by scripts/in_game/common/scripted_effects/gen_towards_victory_leaderboard.py
#   Data:    data/victory_paths.yaml
#   Regen:   conda run --no-capture-output -n eu5 python scripts/in_game/common/scripted_effects/gen_towards_victory_leaderboard.py
# Do not edit directly - modify the data file and re-run the generator.

# Rebuilds the victory situation's per-path global top five.
# Scope: situation:tv_victory_situation
"""

T = "\t"


def emit(lines: list[str], level: int = 0, text: str = "") -> None:
    lines.append(f"{T * level}{text}" if text else "")


def rank_var(pid: str, rank: int) -> str:
    return f"tv_{pid}_rank_{rank}_country"


def append_clear_rank_vars(lines: list[str], level: int, paths: list[dict]) -> None:
    for path in paths:
        pid = path["id"]
        for rank in range(1, 6):
            emit(lines, level, f"remove_variable = {rank_var(pid, rank)}")


def append_pool_rebuild(lines: list[str], level: int) -> None:
    emit(lines, level, "clear_global_variable_list = tv_country_pool")
    emit(lines, level, "every_country = {")
    emit(lines, level + 1, "tv_update_all_progress_pct_effect = yes")
    emit(lines, level + 1, "add_to_global_variable_list = { name = tv_country_pool  target = this }")
    emit(lines, level, "}")


def append_rank_pass(lines: list[str], level: int, pid: str, rank: int) -> None:
    emit(lines, level, "if = {")
    emit(lines, level + 1, "limit = {")
    if rank > 1:
        for previous in range(1, rank):
            emit(lines, level + 2, "custom_tooltip = {")
            emit(lines, level + 3, f"text = TV_HAS_RANK_{previous}_COUNTRY_TT")
            emit(lines, level + 3, f"has_variable = {rank_var(pid, previous)}")
            emit(lines, level + 2, "}")
    emit(lines, level + 2, "global_variable_list_size = {")
    emit(lines, level + 3, "name = tv_country_pool")
    emit(lines, level + 3, f"value > {rank - 1}")
    emit(lines, level + 2, "}")
    emit(lines, level + 1, "}")
    emit(lines, level + 1, "ordered_in_global_list = {")
    emit(lines, level + 2, "variable = tv_country_pool")
    emit(lines, level + 2, f"order_by = {{ add = {{ value = var:tv_{pid}_progress_pct }} }}")
    if rank > 1:
        emit(lines, level + 2, "limit = {")
        for previous in range(1, rank):
            emit(lines, level + 3, f"this != situation:tv_victory_situation.var:{rank_var(pid, previous)}")
        emit(lines, level + 2, "}")
    emit(lines, level + 2, "max = 1")
    emit(lines, level + 2, "check_range_bounds = no")
    emit(lines, level + 2, "situation:tv_victory_situation = {")
    emit(lines, level + 3, f"set_variable = {{ name = {rank_var(pid, rank)}  value = prev }}")
    emit(lines, level + 2, "}")
    emit(lines, level + 1, "}")
    emit(lines, level, "}")


def append_path_ranking(lines: list[str], level: int, path: dict) -> None:
    pid = path["id"]
    emit(lines)
    emit(lines, level, f"# {pid.capitalize()} path top five")
    for rank in range(1, 6):
        append_rank_pass(lines, level, pid, rank)


def generate(data: dict) -> str:
    paths = sorted(data["paths"], key=lambda path: int(path["gui"]["order"]))
    lines = [HEADER.rstrip(), "", "tv_update_leaderboard_effect = {"]
    append_clear_rank_vars(lines, 1, paths)
    emit(lines)
    append_pool_rebuild(lines, 1)
    for path in paths:
        append_path_ranking(lines, 1, path)
    lines.append("}")
    lines.append("")
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--dry", action="store_true", help="Print to stdout instead of writing")
    args = parser.parse_args()

    with DATA_FILE.open(encoding="utf-8-sig") as file:
        data = yaml.safe_load(file)

    content = generate(data)
    if args.dry:
        print(content)
    else:
        OUT_FILE.parent.mkdir(parents=True, exist_ok=True)
        OUT_FILE.write_text(content, encoding="utf-8-sig")
        print(f"Written: {OUT_FILE.relative_to(REPO_ROOT)}")


if __name__ == "__main__":
    main()
